"""Hourly station product from logger dumps (rules in /app/docs)."""
import json
import math
import os
import re
import sys
from datetime import datetime
from fractions import Fraction

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {
    "temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
    "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000),
}
F = Fraction
FACTORS = {
    ("rh", "frac"): F(100),
    ("pres", "kPa"): F(10),
    ("pres", "inHg"): F("33.8638866667"),
    ("pres", "mmHg"): F("1.33322387415"),
    ("wspd", "kmh"): F(1) / F(3.6).limit_denominator(1000),
    ("wspd", "kn"): F(1852, 3600),
    ("wspd", "mph"): F("0.44704"),
}
DIRECTIVE = re.compile(r"^# *([a-z]+):(.*)$")
TIME_RE = re.compile(r"(\d{4})-(\d\d)-(\d\d)[ T](\d\d):(\d\d):(\d\d)")
EPOCH = datetime(1970, 1, 1)


def parse_time(text):
    m = TIME_RE.fullmatch(text.strip())
    y, mo, d, h, mi, s = (int(x) for x in m.groups())
    return int((datetime(y, mo, d, h, mi, s) - EPOCH).total_seconds())


def parse_tz(text):
    text = text.strip()
    if text == "Z":
        return 0
    sign = -1 if text[0] == "-" else 1
    hh, mm = text[1:].split(":")
    return sign * (int(hh) * 3600 + int(mm) * 60)


def is_missing(s):
    if s == "" or s == "---" or s.lower() == "nan":
        return True
    if re.fullmatch(r"-9999(\.0*)?", s):
        return True
    return False


def convert(q, unit, s):
    """Return the canonical value as a Fraction, or None when missing/out of range."""
    if is_missing(s):
        return None
    try:
        v = F(s)
    except (ValueError, ZeroDivisionError):
        return None
    if q == "temp":
        if unit == "degF":
            v = (v - 32) * 5 / 9
        elif unit == "K":
            v = v - F("273.15")
    elif q == "rain":
        if unit.startswith("tips:"):
            try:
                v = v * F(unit[5:])
            except (ValueError, ZeroDivisionError):
                return None
    else:
        if unit == "kmh" and q == "wspd":
            v = v / F("3.6")
        else:
            f = FACTORS.get((q, unit))
            if f is not None:
                v = v * f
    lo, hi = RANGES[q]
    if v < lo or v > hi:
        return None
    return v


def read_dump(path):
    """Return dict with station, upload, interval, rows, syncs."""
    with open(path, "rb") as fh:
        data = fh.read()
    text = data.decode("utf-8", errors="replace")
    if text.startswith("\ufeff"):
        text = text[1:]
    info = {"station": None, "upload": 0, "interval": None, "rows": [], "syncs": []}
    tz = 0
    columns = None
    units = {}
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if not line.strip():
            continue
        if line[0] == "#":
            m = DIRECTIVE.match(line)
            if not m:
                continue
            key, value = m.group(1), m.group(2).strip()
            if key == "station":
                info["station"] = value
            elif key == "upload":
                info["upload"] = int(value)
            elif key == "interval":
                info["interval"] = int(float(value))
            elif key == "tz":
                tz = parse_tz(value)
            elif key == "columns":
                columns = [c.strip() for c in value.split(",")]
            elif key == "units":
                for pair in value.split():
                    if "=" in pair:
                        k, u = pair.split("=", 1)
                        units[k] = u
            elif key == "sync":
                lm = re.search(r"logger=\s*(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)", value)
                rm = re.search(r"ref=\s*(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)", value)
                if lm and rm:
                    t = parse_time(lm.group(1)) - tz
                    info["syncs"].append((t, parse_time(rm.group(1)) - t))
            continue
        if columns is None:
            continue
        fields = [x.strip() for x in line.split(",")]
        if len(fields) != len(columns):
            continue
        row = dict(zip(columns, fields))
        if "time" not in row or not TIME_RE.fullmatch(row["time"]):
            continue
        t = parse_time(row["time"]) - tz
        vals = {}
        for q in QUANTITIES:
            if q in row:
                v = convert(q, units.get(q, "canonical"), row[q])
                if v is not None:
                    vals[q] = float(v)
        info["rows"].append((t, vals))
    return info


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        path = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(path):
            continue
        d = read_dump(path)
        if d["station"] is None:
            continue
        st = stations.setdefault(d["station"], {"interval": None, "rows": {}, "syncs": {}})
        if d["interval"] is not None and (st["interval"] is None or d["upload"] >= st.get("iu", -1)):
            st["interval"] = d["interval"]
            st["iu"] = d["upload"]
        for t, vals in d["rows"]:
            old = st["rows"].get(t)
            if old is None or d["upload"] > old[0]:
                st["rows"][t] = (d["upload"], vals)
        for t, off in d["syncs"]:
            old = st["syncs"].get(t)
            if old is None or d["upload"] > old[0]:
                st["syncs"][t] = (d["upload"], off)

    result = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st["rows"]:
            continue
        interval = st["interval"]
        expected = 3600 // interval
        sync = sorted((t, o) for t, (_, o) in st["syncs"].items())

        def offset(t):
            if not sync:
                return 0
            if t <= sync[0][0]:
                return sync[0][1]
            if t >= sync[-1][0]:
                return sync[-1][1]
            lo, hi = 0, len(sync) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if sync[mid][0] <= t:
                    lo = mid
                else:
                    hi = mid
            t1, o1 = sync[lo]
            t2, o2 = sync[hi]
            return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)

        rows = []
        for t, (_, vals) in st["rows"].items():
            rows.append((t + offset(t), t, vals))
        rows.sort(key=lambda r: (r[0], r[1]))

        def hour_of(c):
            return -((-c) // 3600)

        n = {}
        sums = {}
        vec = {}
        rain = {}
        prev = None
        for c, _, vals in rows:
            h = hour_of(c)
            for q in ("temp", "rh", "pres", "wspd"):
                if q in vals:
                    n[(h, q)] = n.get((h, q), 0) + 1
                    sums.setdefault((h, q), []).append(vals[q])
            if "wdir" in vals:
                n[(h, "wdir")] = n.get((h, "wdir"), 0) + 1
                if vals.get("wspd", 0) > 0:
                    a = math.radians(vals["wdir"])
                    e = vec.setdefault(h, [0.0, 0.0, 0])
                    e[0] += math.sin(a)
                    e[1] += math.cos(a)
                    e[2] += 1
            if "rain" in vals:
                r = vals["rain"]
                n[(h, "rain")] = n.get((h, "rain"), 0) + 1
                if prev is not None and 2 * (c - prev[0]) <= 5 * interval:
                    inc = r - prev[1] if r >= prev[1] else r
                    rain.setdefault(h, []).append(inc)
                prev = (c, r)

        first = hour_of(rows[0][0])
        last = hour_of(rows[-1][0])
        hours = []
        for h in range(first, last + 1):
            entry = {"hour": datetime.utcfromtimestamp(h * 3600).strftime("%Y-%m-%dT%H:00:00Z")}
            for q in QUANTITIES:
                cnt = n.get((h, q), 0)
                ok = cnt * 4 >= expected * 3 and cnt > 0
                value = None
                if ok:
                    if q in ("temp", "rh", "pres", "wspd"):
                        value = round(math.fsum(sums[(h, q)]) / cnt, 2)
                    elif q == "wdir":
                        e = vec.get(h)
                        if e and e[2]:
                            ang = math.degrees(math.atan2(e[0], e[1])) % 360
                            value = round(ang, 2)
                            if value >= 360:
                                value = 0.0
                    else:
                        value = round(math.fsum(rain.get(h, [])), 2)
                        value = value + 0.0
                entry[q] = {"value": value, "n": cnt}
            hours.append(entry)
        result.append({"station": sid, "interval_s": interval, "hours": hours})

    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump({"stations": result}, fh, indent=1)
        fh.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
